 begin perform public.patient_chat_inbox();raise exception 'FAIL patient inbox access';exception when insufficient_privilege then null;end;
 perform public.mark_patient_chat_read(pp,foreign_op);if exists(select 1 from public.patient_chat_reads where patient_id=pp) then raise exception 'FAIL foreign watermark';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',au,'role','authenticated','aal','aal1')::text,true);
