 perform public.mark_patient_chat_read(pp,attachment_op);if public.patient_chat_unread_total()<>0 then raise exception 'FAIL admin read receipt';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal1')::text,true);perform public.mark_patient_chat_read(pp,reply);
 if (select patient_seen_seq from public.patient_chat_reads where patient_id=pp)<>(a->>'seq')::bigint then raise exception 'FAIL patient read receipt';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated','aal','aal1')::text,true);
 if exists(select 1 from public.patient_messages) or exists(select 1 from public.patient_chat_reads) then raise exception 'FAIL CRM staff chat leak';end if;
